<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('admin');$pdo=db();
$stats=$pdo->query("SELECT (SELECT COUNT(*) FROM users WHERE role='donor') donors,(SELECT COUNT(*) FROM charities) charities,(SELECT COUNT(*) FROM clothing_requests) requests,(SELECT COUNT(*) FROM donation_pledges) pledges,(SELECT COUNT(*) FROM appointments WHERE status='booked') appointments,(SELECT COALESCE(SUM(di.quantity),0) FROM donation_items di JOIN donation_pledges dp ON dp.id=di.pledge_id WHERE dp.status='received') received")->fetch();
$activity=$pdo->query("SELECT al.*,u.name FROM activity_log al LEFT JOIN users u ON u.id=al.user_id ORDER BY al.created_at DESC LIMIT 8")->fetchAll();$latest=$pdo->query("SELECT cr.title,cr.status,cr.created_at,c.organization_name FROM clothing_requests cr JOIN charities c ON c.id=cr.charity_id ORDER BY cr.created_at DESC LIMIT 6")->fetchAll();
$pageTitle='Admin dashboard';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell"><div class="welcome-row"><div><span class="eyebrow">System stewardship</span><h1>Giftly control room.</h1><p>Keep the community safe, responsive, and moving useful things where they’re needed.</p></div><a class="button" href="<?=e(url('admin/users.php'))?>">Manage people →</a></div>
<div class="stat-cards"><article class="stat-card"><span class="label">Donors</span><strong><?=$stats['donors']?></strong><small>registered givers</small></article><article class="stat-card"><span class="label">Charities</span><strong><?=$stats['charities']?></strong><small>organisation accounts</small></article><article class="stat-card"><span class="label">Requests</span><strong><?=$stats['requests']?></strong><small>all-time clothing needs</small></article><article class="stat-card"><span class="label">Received items</span><strong><?=$stats['received']?></strong><small>confirmed donations</small></article></div>
<div class="layout-two"><div class="panel"><div class="panel-heading"><h2>Latest charity requests</h2><a class="text-link" href="<?=e(url('admin/requests.php'))?>">View requests →</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Request</th><th>Charity</th><th>Created</th><th>Status</th></tr></thead><tbody><?php foreach($latest as $r):?><tr><td><strong><?=e($r['title'])?></strong></td><td><?=e($r['organization_name'])?></td><td><?=format_date($r['created_at'])?></td><td><span class="status <?=e(status_class($r['status']))?>"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div><div style="margin-top:17px;display:flex;gap:9px;flex-wrap:wrap"><a class="button button-small button-outline" href="<?=e(url('admin/donations.php'))?>">Pledges (<?=$stats['pledges']?>)</a><a class="button button-small button-outline" href="<?=e(url('admin/donations.php#appointments'))?>">Appointments (<?=$stats['appointments']?>)</a></div></div><aside class="panel"><div class="panel-heading"><h2>Recent activity</h2></div><?php if(!$activity):?><div class="empty">No activity recorded yet.</div><?php else:foreach($activity as $item):?><article class="activity-item"><div class="activity-icon">✦</div><div><p><strong><?=e($item['name']??'System')?></strong> <?=e($item['action'])?></p><time><?=format_date($item['created_at'],'d M · H:i')?></time></div></article><?php endforeach;endif;?></aside></div></div></section>
